import { chromium } from 'playwright'

const url = process.argv[2] || 'http://127.0.0.1:8081/'
const browser = await chromium.launch()
const page = await browser.newPage()
const logs = []
page.on('console', (m) => logs.push(`[console.${m.type()}] ${m.text()}`))
page.on('pageerror', (e) => logs.push(`[pageerror] ${e.message}`))
page.on('requestfailed', (r) => logs.push(`[reqfail] ${r.url()} :: ${r.failure()?.errorText}`))

try {
  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 30000 })
} catch (e) {
  console.log('GOTO ERR', e.message)
}
await page.waitForTimeout(6000)

const state = await page.evaluate(() => {
  const q = (s) => document.querySelector(s)
  const sk = q('.page-skeleton') || q('.app-main-skeleton') || q('.portal-skeleton')
  return {
    url: location.href,
    title: document.title,
    hasPageSkeleton: !!q('.page-skeleton'),
    hasAppMainSkeleton: !!q('.app-main-skeleton'),
    hasPortalSkeleton: !!q('.portal-skeleton'),
    skeletonVisible: !!sk,
    pageBoxSkeletonClass: q('.page-box') ? q('.page-box').className : null,
    bodyTextLen: document.body.innerText.trim().length,
    bodySnippet: document.body.innerText.trim().slice(0, 120)
  }
})
console.log('=== STATE ===')
