  // 接口慢/挂起时（弱网、本地代理后端不可达，axios 超时最长 100s），
  // 这里用 Promise.race 兜一个最长等待时长，到点无论请求是否返回都先揭开骨架，
  // 公告列表等请求真正返回后再补进页面，避免用户"刷新一直停在骨架屏"。
  let noticeSettled = false
