import { chromium } from 'playwright'
const browser = await chromium.launch()

async function run(hangNotice, label) {
  const page = await browser.newPage()
  if (hangNotice) await page.route('**/externalInfo/publicNotice/page', () => { /* never fulfill */ })
  const t0 = Date.now()
  await page.goto('http://127.0.0.1:8081/#/UnifiedLogin', { waitUntil: 'domcontentloaded', timeout: 30000 })
  let readyAt = null, sawSkeleton = false
  for (let i = 0; i < 150; i++) {
    const s = await page.evaluate(() => ({
      hasSk: !!document.querySelector('.page-skeleton'),
      len: document.body.innerText.trim().length
    }))
    if (s.hasSk) sawSkeleton = true
    // ready = content rendered AND no skeleton overlay remains
    if (!s.hasSk && s.len > 100) { readyAt = Date.now() - t0; break }
    await page.waitForTimeout(100)
  }
  const final = await page.evaluate(() => ({
    hasPageSkeleton: !!document.querySelector('.page-skeleton'),
    boxClass: document.querySelector('.page-box')?.className || null,
    len: document.body.innerText.trim().length
  }))
  console.log(`\n### ${label} (hangNotice=${hangNotice}) sawSkeleton=${sawSkeleton}`)
  console.log('content ready after ms:', readyAt, ' final:', JSON.stringify(final))
  await page.close()
}

await run(false, 'normal')
await run(true, 'HANG API')
await browser.close()

